import{_ as i,C as s,o as l,c as d,ag as a,E as o,w as n,j as t}from"./chunks/framework.4Y_9FogC.js";const p="/assets/Theengs-app-home-reduced-1280.Co1bL4MP.png",c="/assets/Theengs-app-live.FiHWtRDu.png",k=JSON.parse('{"title":"Theengs BLE mobile application","description":"","frontmatter":{"title":"Theengs BLE mobile application"},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1780765817000}'),h={name:"index.md"};function g(m,e,u,b,y,f){const r=s("center");return l(),d("div",null,[e[2]||(e[2]=a('<h1 id="theengs-ble-mobile-application" tabindex="-1">Theengs BLE mobile application <a class="header-anchor" href="#theengs-ble-mobile-application" aria-label="Permalink to &quot;Theengs BLE mobile application&quot;">​</a></h1><h2 id="🌟-local-smart-sensor-integration-🌟" tabindex="-1">🌟 Local Smart Sensor Integration 🌟 <a class="header-anchor" href="#🌟-local-smart-sensor-integration-🌟" aria-label="Permalink to &quot;🌟 Local Smart Sensor Integration 🌟&quot;">​</a></h2><p>Theengs App seamlessly reads a wide array of Bluetooth Low Energy (BLE) sensors, gathering real-time data on environmental parameters such as temperature, humidity, moisture, soil, battery voltage, BBQ probes, motion, and more. It can also <strong>control SwitchBot actuators</strong> (Bot S1, Curtain, Blind Tilt) directly over BLE. Readings are displayed intuitively and can be integrated with your Smart Home setup via MQTT (plaintext or TLS, with Home Assistant auto-discovery). Compatible with platforms like Home Assistant, Theengs App is a vendor-agnostic reader of <a href="https://decoder.theengs.io/devices/devices.html" target="_blank" rel="noreferrer">your sensors</a>.</p><p><img src="'+p+'" alt="Iot"></p><h2 id="🤖-control-your-switchbot-devices" tabindex="-1">🤖 Control Your SwitchBot Devices <a class="header-anchor" href="#🤖-control-your-switchbot-devices" aria-label="Permalink to &quot;🤖 Control Your SwitchBot Devices&quot;">​</a></h2><p>Theengs App goes beyond reading sensors: it can <strong>control SwitchBot actuators</strong> directly over Bluetooth. Open, close or tilt a SwitchBot Curtain or Blind Tilt from the app, or trigger a SwitchBot Bot S1 in Press or Switch mode. The app pairs to the device on demand for each action, then releases the connection, keeping things local and private.</p><p>Supported SwitchBot devices:</p><ul><li><strong>Bot S1 / SmartSwitch</strong> — On, Off, Push-Pull, with Press / Switch mode and inverted-direction option</li><li><strong>Curtain 2 / Curtain 3</strong> — Open, Close, Stop, move to position (0–100 %), High / Low speed</li><li><strong>Blind Tilt</strong> — Open, Close up, Close down, Stop, tilt to position (-100…100 %)</li></ul><h2 id="🔥-elevate-your-grilling-game" tabindex="-1">🔥 Elevate Your Grilling Game <a class="header-anchor" href="#🔥-elevate-your-grilling-game" aria-label="Permalink to &quot;🔥 Elevate Your Grilling Game&quot;">​</a></h2><p>Theengs App now offers a dedicated live monitoring feature for BBQ enthusiasts. Track your cooking with a dynamic chart that displays temperature trends in real time. Set personalized thresholds for different cooking stages and receive instant notifications based on these criteria. Whether you prefer your meat rare, medium, or well-done, Theengs App ensures your grilling is done to perfection.</p><div style="text-align:center;"><p><img src="'+c+'" alt="live bbq monitoring"></p></div><h2 id="🔒respecting-your-privacy" tabindex="-1">🔒Respecting Your Privacy <a class="header-anchor" href="#🔒respecting-your-privacy" aria-label="Permalink to &quot;🔒Respecting Your Privacy&quot;">​</a></h2><p>With Theengs App, your data stays local by default. For more details, please refer to our <a href="https://app.theengs.io/use/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><h2 id="🏡-take-control-with-smart-home-integration" tabindex="-1">🏡 Take control with Smart Home Integration <a class="header-anchor" href="#🏡-take-control-with-smart-home-integration" aria-label="Permalink to &quot;🏡 Take control with Smart Home Integration&quot;">​</a></h2><p>Theengs App syncs with platforms like Home Assistant via MQTT. Record sensor data on your preferred server - your home, your choice.</p><h2 id="📲-choose-your-platform-and-download-now" tabindex="-1">📲 Choose Your Platform and Download Now <a class="header-anchor" href="#📲-choose-your-platform-and-download-now" aria-label="Permalink to &quot;📲 Choose Your Platform and Download Now&quot;">​</a></h2><br>',17)),o(r,null,{default:n(()=>[...e[0]||(e[0]=[t("a",{href:"https://apps.apple.com/us/app/theengs-ble/id6443457651?itsct=apps_box_badge&itscg=30200",style:{display:"inline-block",overflow:"hidden","border-radius":"13px",width:"250px",height:"83px"}},[t("img",{src:"https://tools.applemediaservices.com/api/badges/download-on-the-app-store/black/en-us?size=250x83&releaseDate=1667088000&h=c822551038086181cfac2a32c96cd47e",alt:"Download on the App Store",style:{"border-radius":"13px",width:"250px",height:"83px"}})],-1)])]),_:1}),o(r,null,{default:n(()=>[...e[1]||(e[1]=[t("a",{href:"https://play.google.com/store/apps/details?id=com.theengs.app&pcampaignid=pcampaignidMKT-Other-global-all-co-prtnr-py-PartBadge-Mar2515-1"},[t("img",{alt:"Get it on Google Play",src:"https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png",width:"300px/"})],-1)])]),_:1}),e[3]||(e[3]=a('<div class="tip custom-block"><p class="custom-block-title">Note</p><p>The Theengs app reads data that is &#39;broadcasted&#39; by devices, operating primarily in a passive mode for most sensors — the app captures data as it is emitted, without any direct connection. A direct BLE connection is opened on demand for:</p><ul><li><strong>Mi Flora</strong> and <strong>ThermoBeacon</strong> — to retrieve historical data</li><li><strong>BM2</strong> and <strong>BM6</strong> battery monitors — to read voltage and additional metrics</li><li><strong>SwitchBot Bot S1</strong>, <strong>Curtain 2 / 3</strong> and <strong>Blind Tilt</strong> — to send a control action; the link is released once the action completes</li></ul><p>BBQ Live monitoring and notifications require the app to be active on the sensor screen. On Android, the foreground BLE-scan service keeps general sensor updates flowing when the screen is off (a persistent notification is required by the OS).</p></div><h3 id="features-comparison-between-operating-systems" tabindex="-1">Features comparison between Operating Systems <a class="header-anchor" href="#features-comparison-between-operating-systems" aria-label="Permalink to &quot;Features comparison between Operating Systems&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">OS</th><th style="text-align:center;">Real time data</th><th style="text-align:center;">BBQ monitoring</th><th style="text-align:center;">Battery monitors</th><th style="text-align:center;">SwitchBot control</th><th style="text-align:center;">MQTT integration (incl. TLS)</th><th style="text-align:center;">Running in background</th><th style="text-align:center;">Home Assistant Auto Discovery</th></tr></thead><tbody><tr><td style="text-align:center;">iOS</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;"></td><td style="text-align:center;">☑️</td></tr><tr><td style="text-align:center;">Android</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️ <em>(foreground service)</em></td><td style="text-align:center;">☑️</td></tr></tbody></table><p><strong>Theengs app</strong> can be used as a standalone solution or as a complementary solution to <a href="https://docs.openmqttgateway.com/" target="_blank" rel="noreferrer">OpenMQTTGateway</a> and/or <a href="https://gateway.theengs.io" target="_blank" rel="noreferrer">Theengs gateway</a> if you want a continuously running gateway.</p><h3 id="third-party-projects-used-by-theengs-app" tabindex="-1">Third party projects used by Theengs app <a class="header-anchor" href="#third-party-projects-used-by-theengs-app" aria-label="Permalink to &quot;Third party projects used by Theengs app&quot;">​</a></h3><ul><li><a href="https://www.qt.io" target="_blank" rel="noreferrer">Qt</a> (<a href="https://www.gnu.org/licenses/lgpl-3.0.txt" target="_blank" rel="noreferrer">LGPL 3</a>)</li><li><a href="https://www.qt.io" target="_blank" rel="noreferrer">QtMqtt</a> (<a href="https://www.gnu.org/licenses/gpl-3.0.txt" target="_blank" rel="noreferrer">GPL 3</a>)</li><li><a href="https://arduinojson.org/" target="_blank" rel="noreferrer">Arduino Json</a> (<a href="https://opensource.org/licenses/MIT" target="_blank" rel="noreferrer">MIT</a>)</li><li><a href="https://decoder.theengs.io/" target="_blank" rel="noreferrer">Decoder</a> (<a href="https://www.gnu.org/licenses/gpl-3.0.txt" target="_blank" rel="noreferrer">GPL 3</a>)</li><li><a href="https://github.com/jpnurmi/statusbar" target="_blank" rel="noreferrer">MobileUI</a> (<a href="https://opensource.org/licenses/MIT" target="_blank" rel="noreferrer">MIT</a>)</li><li><a href="https://github.com/ekke/ekkesSHAREexample" target="_blank" rel="noreferrer">MobileSharing</a> (<a href="https://github.com/ekke/ekkesSHAREexample/blob/master/LICENSE" target="_blank" rel="noreferrer">license</a>)</li><li><a href="https://github.com/itay-grudev/SingleApplication" target="_blank" rel="noreferrer">SingleApplication</a> (<a href="https://opensource.org/licenses/MIT" target="_blank" rel="noreferrer">MIT</a>)</li><li>RC4 code from Christophe Devine (<a href="https://www.gnu.org/licenses/old-licenses/gpl-2.0.txt" target="_blank" rel="noreferrer">GPL 2</a>)</li><li>Graphical resources: <a href="https://github.com/theengs/app/blob/development/assets/COPYING" target="_blank" rel="noreferrer">assets/COPYING</a></li></ul><h3 id="acknowledgements" tabindex="-1">Acknowledgements <a class="header-anchor" href="#acknowledgements" aria-label="Permalink to &quot;Acknowledgements&quot;">​</a></h3><p><em>App Store and Apple logo are registered trademarks of Apple Inc.</em></p><p><em>Google Play and the Google Play logo are trademarks of Google LLC.</em></p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>All product and company names are trademarks or registered trademarks of their respective holders. Use of them does not imply any affiliation with or endorsement by them.</p></div>',10))])}const _=i(h,[["render",g]]);export{k as __pageData,_ as default};
